
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_b88_6311g_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_b88_6311g", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.351948108338474e+00, -4.270514163241824e+00, -4.156500013524238e+00, -3.998758059879370e+00, -3.784219806024993e+00, -3.499515612186870e+00, -3.134731987946378e+00, -2.690003412963142e+00, -2.183640928680621e+00, -1.652924645319471e+00, -1.124233620605205e+00, -7.183586437507585e-01, -6.070217230687766e-01, -5.093008816828039e-01, -3.791707723864806e-01, -2.538597638390309e-01, -1.591053752736933e-01, -9.716128441947944e-02, -6.118701712262671e-02, -4.173134032435093e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


